urlset:
{%- for post in posts -%}
  {%- if post.layout == 'post' or post.layout == 'page' -%} 

  https://blog.flwolfy.xyz/{{ post.path | uriencode }}
  {% if post.updated %}
  {{ post.updated.toISOString().split('T')[0] }}
  {% elif post.date %}
  {{ post.date.toISOString().split('T')[0] }}
  {% endif %}
  monthly
  0.6

  {%- endif -%}
{%- endfor -%}


  https://blog.flwolfy.xyz/
  {% if posts[posts.length - 1].updated %}
  {{ posts[posts.length - 1].updated.toISOString().split('T')[0] }}
  {% elif posts[posts.length - 1].date %}
  {{ posts[posts.length - 1].date.toISOString().split('T')[0] }}
  {% endif %}
  daily
  1.0
